  "CodeContent": "// ============================================================================
// heliomhd3d.cu
// Hyper-Optimized 3D Spherical Ideal-MHD + Passive Heavy-Ion Scalar Solver
// for the Inner Heliosphere (0.1 AU to 2.4 AU) & Comet 3I/ATLAS SWCX Modeling
//
// Author: Argon (Gemini 4 Argon High)
// Architecture: CUDA (Compute Capability 8.9, RTX 4080 SUPER) + C++17
//
// Features:
//  - Full 3D Spherical (r, theta, phi) Finite-Volume Ideal MHD in Inertial HCI
//  - Well-Balanced Spherical Geometric Source Terms (exact hydrostatic balance)
//  - Stokes-Consistent Spherical Induction Update + GLM-Powell div(B) Cleaning
//  - 2nd-Order TVD Piecewise Linear Reconstruction (MC / Minmod limiter)
//  - HLL + Decoupled 2x2 Exact GLM Riemann Fluxes
//  - 2nd-Order Strong-Stability-Preserving Runge-Kutta (SSPRK2) Time Stepping
//  - Passive Advection of Heavy-Ion Fraction f_hi (Schwadron & Cravens 2000)
//    and ICME Tracer f_cme
//  - Built-in Verification & Production Modes:
//      1. brio_wu       : 1D Brio-Wu (1988) MHD shock tube convergence suite
//      2. parker_steady : 3D Axisymmetric Weber-Davis / Parker spiral benchmark
//      3. tilted_cir    : 3D Tilted-Dipole (30 deg) CIR stream interaction
//      4. solar_wind    : Time-dependent Nov-Dec 2025 3I/ATLAS simulation
// ============================================================================

#include <cuda_runtime.h>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <sstream>
#include <algorithm>
#include <chrono>

#define CUDA_CHECK(call)                                                       \
    do {                                                                       \
        cudaError_t err = (call);                                              \
        if (err != cudaSuccess) {                                              \
            fprintf(stderr, "CUDA Error at %s:%d: %s\n", __FILE__, __LINE__,   \
                    cudaGetErrorString(err));                                  \
            exit(EXIT_FAILURE);                                                \
        }                                                                      \
    } while (0)

// ----------------------------------------------------------------------------
// Physical & Code Unit Constants
//   Length unit   L0 = 1 AU = 1.495978707e11 m
//   Velocity unit V0 = 100 km/s = 1.0e5 m/s
//   Time unit     T0 = L0 / V0 = 1.495978707e6 s = 17.314568368 days
//   Density unit  N0 = 1 cm^-3 (m_p = 1.6726219e-27 kg)
//   Magnetic unit B0 = sqrt(mu0 * N0 * m_p * V0^2) = 4.5846718 nT
//   Temp scale    T_SCALE = m_p * V0^2 / (2 * k_B) = 605336.0 K
// ----------------------------------------------------------------------------
constexpr double PI = 3.14159265358979323846;
constexpr double DEG2RAD = PI / 180.0;
constexpr double RAD2DEG = 180.0 / PI;
constexpr double CODE_V0_KMS = 100.0;
constexpr double CODE_T0_DAYS = 17.314568368055556;
constexpr double CODE_B0_NT = 4.584671825;
constexpr double CODE_T_SCALE_K = 605336.0;
constexpr double OMEGA_SUN_CODE = (14.1844 * DEG2RAD) * CODE_T0_DAYS; // 4.286472 rad/T0
constexpr double GM_SUN_CODE = 0.08871279;                            // GM_sun / (L0 * V0^2)

// 10 State Variables per Cell:
// Conservative: 0:rho, 1:mom_r, 2:mom_th, 3:mom_ph, 4:Br, 5:Bth, 6:Bph, 7:E, 8:psi, 9:rho_fhi
constexpr int NVAR = 10;
constexpr int NGHOST = 2;

struct SimConfig {
    std::string mode = "solar_wind";
    std::string bc_file = "data/processed/bc_mode3_assimilated.bin";
    std::string traj_file = "data/processed/trajectories.bin";
    std::string cme_file = "data/processed/cmes_hci.txt";
    std::string out_prefix = "outputs/run";
    int nr = 160;
    int nth = 32;
    int nph = 180;
    double r_in = 0.10;
    double r_out = 2.40;
    double lat_max_deg = 60.0;
    double gamma = 1.50;
    double cfl = 0.35;
    int enable_grav = 1;
    int enable_mag = 1;
    int enable_cmes = 0;
    int save_slices = 0;
    double relax_days = 14.0;
    double mjd_start = 60998.0; // 2025-11-19
    double mjd_end = 61015.0;   // 2025-12-06
    double mjd_ref = 61012.0;
    double phase_ref_deg = 326.27515176;
};

struct CMEEvent {
    double mjd_launch;
    double lat_deg;
    double lon_hci_deg;
    double half_width_deg;
    double v_kms;
};

// ----------------------------------------------------------------------------
// Device Helper Functions: Primitive <-> Conservative & Limiter
// ----------------------------------------------------------------------------
__host__ __device__ inline double minmod(double a, double b) {
    if (a * b <= 0.0) return 0.0;
    return (fabs(a) < fabs(b)) ? a : b;
}

__host__ __device__ inline double mc_limiter(double a, double b) {
    if (a * b <= 0.0) return 0.0;
    double c = 0.5 * (a + b);
    double m = (fabs(2.0 * a) < fabs(2.0 * b)) ? 2.0 * a : 2.0 * b;
    return (fabs(m) < fabs(c)) ? ((c > 0.0) ? fabs(m) : -fabs(m)) : c;
}

__host__ __device__ inline void cons_to_prim(const double U[NVAR], double W[NVAR], double gamma) {
    double rho = fmax(U[0], 1e-6);
    double inv_rho = 1.0 / rho;
    double vr = U[1] * inv_rho;
    double vth = U[2] * inv_rho;
    double vph = U[3] * inv_rho;
    double br = U[4];
    double bth = U[5];
    double bph = U[6];
    double v2 = vr * vr + vth * vth + vph * vph;
    double b2 = br * br + bth * bth + bph * bph;
    double p = (gamma - 1.0) * (U[7] - 0.5 * rho * v2 - 0.5 * b2);
    double p_min = 1e-6 * rho; // T_min ~ 0.6 K floor for numerical safety
    if (p < p_min) p = p_min;

    W[0] = rho;
    W[1] = vr;
    W[2] = vth;
    W[3] = vph;
    W[4] = br;
    W[5] = bth;
    W[6] = bph;
    W[7] = p;
    W[8] = U[8];
    W[9] = fmin(fmax(U[9] * inv_rho, 1e-5), 5e-3);
}

__host__ __device__ inline void prim_to_cons(const double W[NVAR], double U[NVAR], double gamma) {
    double rho = fmax(W[0], 1e-6);
    double vr = W[1];
    double vth = W[2];
    double vph = W[3];
    double br = W[4];
    double bth = W[5];
    double bph = W[6];
    double p = fmax(W[7], 1e-6 * rho);
    double v2 = vr * vr + vth * vth + vph * vph;
    double b2 = br * br + bth * bth + bph * bph;

    U[0] = rho;
    U[1] = rho * vr;
    U[2] = rho * vth;
    U[3] = rho * vph;
    U[4] = br;
    U[5] = bth;
    U[6] = bph;
    U[7] = p / (gamma - 1.0) + 0.5 * rho * v2 + 0.5 * b2;
    U[8] = W[8];
    U[9] = rho * W[9];
}

__host__ __device__ inline double fast_magnetosonic_speed(
    double rho, double p, double bn, double bt1, double bt2, double gamma
) {
    double inv_rho = 1.0 / fmax(rho, 1e-6);
    double cs2 = gamma * fmax(p, 1e-8) * inv_rho;
    double b2 = bn * bn + bt1 * bt1 + bt2 * bt2;
    double va2 = b2 * inv_rho;
    double van2 = (bn * bn) * inv_rho;
    double sum = cs2 + va2;
    double disc = fmax(sum * sum - 4.0 * cs2 * van2, 0.0);
    return sqrt(0.5 * (sum + sqrt(disc)));
}

// ----------------------------------------------------------------------------
// 1D HLL + Exact Decoupled GLM Riemann Solver along normal direction `dir`:
//   dir = 0: radial (n=r, t1=th, t2=ph)
//   dir = 1: colatitude (n=th, t1=ph, t2=r)
//   dir = 2: azimuth (n=ph, t1=r, t2=th)
// ----------------------------------------------------------------------------
__host__ __device__ inline void hll_glm_flux(
    const double WL_in[NVAR], const double WR_in[NVAR],
    double Flux[NVAR], int dir, double gamma, double ch
) {
    int in_v = 1 + dir;
    int it1_v = 1 + ((dir + 1) % 3);
    int it2_v = 1 + ((dir + 2) % 3);
    int in_b = 4 + dir;
    int it1_b = 4 + ((dir + 1) % 3);
    int it2_b = 4 + ((dir + 2) % 3);

    double WL[NVAR], WR[NVAR];
    #pragma unroll
    for (int m = 0; m < NVAR; ++m) {
        WL[m] = WL_in[m];
        WR[m] = WR_in[m];
    }

    // Exact 2x2 Riemann solution for (B_n, psi) subsystem (Dedner et al. 2002)
    double bn_star = 0.5 * (WL[in_b] + WR[in_b]) - 0.5 * (WR[8] - WL[8]) / fmax(ch, 1e-6);
    double psi_star = 0.5 * (WL[8] + WR[8]) - 0.5 * ch * (WR[in_b] - WL[in_b]);
    WL[in_b] = bn_star;
    WR[in_b] = bn_star;
    WL[8] = psi_star;
    WR[8] = psi_star;

    double UL[NVAR], UR[NVAR];
    prim_to_cons(WL, UL, gamma);
    prim_to_cons(WR, UR, gamma);

    double cfL = fast_magnetosonic_speed(WL[0], WL[7], WL[in_b], WL[it1_b], WL[it2_b], gamma);
    double cfR = fast_magnetosonic_speed(WR[0], WR[7], WR[in_b], WR[it1_b], WR[it2_b], gamma);

    double vnL = WL[in_v];
    double vnR = WR[in_v];
    double sL = fmin(vnL - cfL, vnR - cfR);
    double sR = fmax(vnL + cfL, vnR + cfR);

    auto physical_flux = [&](const double W[NVAR], const double U[NVAR], double F[NVAR]) {
        double rho = W[0];
        double vn = W[in_v], vt1 = W[it1_v], vt2 = W[it2_v];
        double bn = W[in_b], bt1 = W[it1_b], bt2 = W[it2_b];
        double b2 = bn * bn + bt1 * bt1 + bt2 * bt2;
        double ptot = W[7] + 0.5 * b2;
        double vdotb = vn * bn + vt1 * bt1 + vt2 * bt2;

        F[0] = rho * vn;
        F[in_v] = rho * vn * vn + ptot - bn * bn;
        F[it1_v] = rho * vn * vt1 - bn * bt1;
        F[it2_v] = rho * vn * vt2 - bn * bt2;
        F[in_b] = psi_star;
        F[it1_b] = vn * bt1 - vt1 * bn;
        F[it2_b] = vn * bt2 - vt2 * bn;
        F[7] = (U[7] + ptot) * vn - bn * vdotb;
        F[8] = ch * ch * bn_star;
        F[9] = F[0] * W[9];
    };

    double FL[NVAR], FR[NVAR];
    physical_flux(WL, UL, FL);
    physical_flux(WR, UR, FR);

    if (sL >= 0.0) {
        #pragma unroll
        for (int m = 0; m < NVAR; ++m) Flux[m] = FL[m];
    } else if (sR <= 0.0) {
        #pragma unroll
        for (int m = 0; m < NVAR; ++m) Flux[m] = FR[m];
    } else {
        double inv_ds = 1.0 / (sR - sL);
        #pragma unroll
        for (int m = 0; m < 8; ++m) {
            Flux[m] = (sR * FL[m] - sL * FR[m] + sL * sR * (UR[m] - UL[m])) * inv_ds;
        }
        Flux[in_b] = psi_star;
        Flux[8] = ch * ch * bn_star;
        // Exact upwind passive scalar advection using the HLL mass flux Flux[0]
        Flux[9] = (Flux[0] >= 0.0) ? (Flux[0] * WL[9]) : (Flux[0] * WR[9]);
    }
}

// ----------------------------------------------------------------------------
// 3D Spherical Indexing Helper
//   Grid dimensions including ghost cells:
//   ir  in [0, nr + 2*NGHOST - 1]  (interior: [NGHOST, nr + NGHOST - 1])
//   ith in [0, nth + 2*NGHOST - 1] (interior: [NGHOST, nth + NGHOST - 1])
//   iph in [0, nph - 1]            (periodic in [0, 2*pi))
// ----------------------------------------------------------------------------
__host__ __device__ inline int idx3d(int ir, int ith, int iph, int nr_tot, int nth_tot, int nph) {
    int ip = (iph % nph + nph) % nph;
    return ((ir * nth_tot + ith) * nph + ip);
}

// ----------------------------------------------------------------------------
// Inner Boundary Condition Kernel at r = r_in (ir < NGHOST)
//   Supports:
//     bc_type = 0: Steady Parker / Weber-Davis Wind
//     bc_type = 1: Tilted-Dipole (30 deg) 3D CIR Benchmark (Odstrcil 2003)
//     bc_type = 2: WSA/In-Situ 2D Boundary Map + Optional Cone CMEs
// ----------------------------------------------------------------------------
__global__ void apply_boundary_conditions_kernel(
    double* __restrict__ d_U,
    const float* __restrict__ d_bc_map, // (4, 90, 180)
    const CMEEvent* __restrict__ d_cmes,
    int n_cmes,
    int nr, int nth, int nph,
    double r_in, double dr,
    double th_min, double dth,
    double dph,
    double gamma,
    double t_code,
    double mjd_current,
    double mjd_ref,
    double phase_ref_deg,
    int bc_type,
    int enable_mag,
    int enable_cmes
) {
    int ith = blockIdx.x * blockDim.x + threadIdx.x;
    int iph = blockIdx.y * blockDim.y + threadIdx.y;
    int nr_tot = nr + 2 * NGHOST;
    int nth_tot = nth + 2 * NGHOST;
    if (ith >= nth_tot || iph >= nph) return;

    int ith_clamped = min(max(ith, NGHOST), nth + NGHOST - 1);
    double th = th_min + (ith_clamped - NGHOST + 0.5) * dth;
    double sin_th = sin(th);
    double lat_deg = 90.0 - th * RAD2DEG;
    double phi = (iph + 0.5) * dph;
    double phi_deg = phi * RAD2DEG;

    // 1. Inner radial ghost cells (ir = 0 .. NGHOST-1)
    for (int ir = 0; ir < NGHOST; ++ir) {
        double r = r_in + (ir - NGHOST + 0.5) * dr;
        double ratio = r_in / r;
        double ratio2 = ratio * ratio;

        double vr_kms = 400.0;
        double np_cm3 = 700.0;
        double br_nT = 300.0;
        double temp_K = 5.0e5;
        double f_hi = 7.0e-4;

        if (bc_type == 0) {
            // Steady Parker Spiral / Weber-Davis benchmark
            vr_kms = 400.0;
            np_cm3 = 700.0 * ratio2;
            br_nT = (enable_mag ? 300.0 : 0.0) * ratio2;
            temp_K = 5.0e5 * pow(ratio2, gamma - 1.0);
            f_hi = 7.646e-4;
        } else if (bc_type == 1) {
            // Tilted-Dipole (alpha = 30 deg) 3D CIR benchmark (Odstrcil 2003; Pomoell & Poedts 2018)
            double alpha_tilt = 30.0 * DEG2RAD;
            double phi_rot = phi - OMEGA_SUN_CODE * t_code;
            double th_cs = 0.5 * PI - asin(sin(alpha_tilt) * sin(phi_rot));
            double dth_sb_deg = fabs(th - th_cs) * cos(alpha_tilt) * RAD2DEG;
            double s_fast = 0.5 * (1.0 + tanh((dth_sb_deg - 12.0) / 4.0));
            double v_slow = 325.0, v_fast = 675.0;
            vr_kms = v_slow + (v_fast - v_slow) * s_fast;
            np_cm3 = 300.0 * pow(v_fast / vr_kms, 2.0) * ratio2;
            double sign_b = (th < th_cs) ? 1.0 : -1.0;
            double hcs_smooth = tanh((th_cs - th) / (3.0 * DEG2RAD));
            br_nT = (enable_mag ? 300.0 * hcs_smooth : 0.0) * ratio2;
            temp_K = 8.0e5 * pow(vr_kms / v_fast, 2.0) * pow(ratio2, gamma - 1.0);
            // Schwadron & Cravens (2000) slow streamer (7.646e-4) vs fast CH (6.329e-4)
            f_hi = 7.646e-4 + (6.329e-4 - 7.646e-4) * s_fast;
            (void)sign_b;
        } else {
            // bc_type == 2: Data-Driven WSA / In-Situ Assimilated 2D Map in Carrington Coordinates
            double clon_deg = fmod(phi_deg - 14.1844 * (mjd_current - mjd_ref) + phase_ref_deg, 360.0);
            if (clon_deg < 0.0) clon_deg += 360.0;

            // Bilinear interpolation on (90, 180) map: lat in [-89, 89] step 2, clon in [1, 359] step 2
            double fj = fmin(fmax((lat_deg - (-89.0)) * 0.5, 0.0), 89.0);
            int j0 = (int)floor(fj);
            int j1 = min(j0 + 1, 89);
            double wj = fj - j0;

            double fi = (clon_deg - 1.0) * 0.5;
            int i0 = ((int)floor(fi) % 180 + 180) % 180;
            int i1 = (i0 + 1) % 180;
            double wi = fi - floor(fi);

            auto interp_plane = [&](int plane) {
                const float* P = d_bc_map + plane * (90 * 180);
                double v00 = P[j0 * 180 + i0];
                double v01 = P[j0 * 180 + i1];
                double v10 = P[j1 * 180 + i0];
                double v11 = P[j1 * 180 + i1];
                return (1.0 - wj) * ((1.0 - wi) * v00 + wi * v01) +
                       wj * ((1.0 - wi) * v10 + wi * v11);
            };

            vr_kms = interp_plane(0);
            np_cm3 = interp_plane(1) * ratio2;
            br_nT = (enable_mag ? interp_plane(2) : 0.0) * ratio2;
            temp_K = interp_plane(3) * pow(ratio2, gamma - 1.0);

            // Schwadron & Cravens (2000) + Koutroumpa et al. (2025) continuous slow/fast heavy-ion fraction
            double s_slow = 0.5 * (1.0 - tanh((vr_kms - 430.0) / 70.0));
            f_hi = 6.329e-4 + (7.646e-4 - 6.329e-4) * s_slow;

            // Optional cone CME superposition at r = r_in
            if (enable_cmes && n_cmes > 0) {
                for (int ic = 0; ic < n_cmes; ++ic) {
                    double dt_days = mjd_current - d_cmes[ic].mjd_launch;
                    // Cone pulse duration at 21.5 R_sun ~ 8 hours (0.333 days)
                    if (dt_days >= -0.05 && dt_days <= 0.35) {
                        double dlat = (lat_deg - d_cmes[ic].lat_deg) * DEG2RAD;
                        double dlon = (phi_deg - d_cmes[ic].lon_hci_deg) * DEG2RAD;
                        double cos_ang = sin(lat_deg * DEG2RAD) * sin(d_cmes[ic].lat_deg * DEG2RAD) +
                                         cos(lat_deg * DEG2RAD) * cos(d_cmes[ic].lat_deg * DEG2RAD) * cos(dlon);
                        double ang_deg = acos(fmin(fmax(cos_ang, -1.0), 1.0)) * RAD2DEG;
                        if (ang_deg < d_cmes[ic].half_width_deg) {
                            double prof_ang = cos(0.5 * PI * ang_deg / d_cmes[ic].half_width_deg);
                            double prof_t = sin(PI * fmin(fmax((dt_days + 0.05) / 0.40, 0.0), 1.0));
                            double shape = prof_ang * prof_ang * prof_t;
                            vr_kms = fmax(vr_kms, vr_kms + (d_cmes[ic].v_kms - vr_kms) * shape);
                            np_cm3 += 4.0 * 125.0 * ratio2 * shape; // ENLIL dcld = 4 * dfast
                            f_hi = fmax(f_hi, f_hi + (1.25e-3 - f_hi) * shape);
                        }
                    }
                    (void)dlat;
                }
            }
        }

        double W[NVAR];
        W[0] = np_cm3;
        W[1] = vr_kms / CODE_V0_KMS;
        W[2] = 0.0;
        W[3] = 0.0;
        W[4] = br_nT / CODE_B0_NT;
        W[5] = 0.0;
        // Parker spiral azimuthal field B_phi = -B_r * (Omega_sun * r * sin(theta) / v_r)
        W[6] = -W[4] * (OMEGA_SUN_CODE * r * sin_th / fmax(W[1], 0.5));
        W[7] = W[0] * (temp_K / CODE_T_SCALE_K);
        W[8] = 0.0;
        W[9] = f_hi;

        double U[NVAR];
        prim_to_cons(W, U, gamma);
        int cell = idx3d(ir, ith, iph, nr_tot, nth_tot, nph);
        int ncells = nr_tot * nth_tot * nph;
        for (int m = 0; m < NVAR; ++m) {
            d_U[m * ncells + cell] = U[m];
        }
    }

    // 2. Outer radial ghost cells (ir = nr + NGHOST .. nr + 2*NGHOST - 1): Supersonic outflow scaling
    for (int ir = nr + NGHOST; ir < nr_tot; ++ir) {
        int ir_src = nr + NGHOST - 1;
        double r_src = r_in + (ir_src - NGHOST + 0.5) * dr;
        double r_dst = r_in + (ir - NGHOST + 0.5) * dr;
        double ratio = r_src / r_dst;
        double ratio2 = ratio * ratio;

        int cell_src = idx3d(ir_src, ith, iph, nr_tot, nth_tot, nph);
        int cell_dst = idx3d(ir, ith, iph, nr_tot, nth_tot, nph);
        int ncells = nr_tot * nth_tot * nph;

        double U_src[NVAR], W[NVAR];
        for (int m = 0; m < NVAR; ++m) U_src[m] = d_U[m * ncells + cell_src];
        cons_to_prim(U_src, W, gamma);

        W[0] *= ratio2;
        W[4] *= ratio2;
        W[5] *= ratio;
        W[6] *= ratio;
        W[7] *= pow(ratio2, gamma);
        W[8] = 0.0;

        double U_dst[NVAR];
        prim_to_cons(U_dst, U_dst, gamma); // dummy init
        prim_to_cons(W, U_dst, gamma);
        for (int m = 0; m < NVAR; ++m) {
            d_U[m * ncells + cell_dst] = U_dst[m];
        }
    }
}

__global__ void apply_lat_boundary_kernel(
    double* __restrict__ d_U, int nr, int nth, int nph, double gamma
) {
    int ir = blockIdx.x * blockDim.x + threadIdx.x;
    int iph = blockIdx.y * blockDim.y + threadIdx.y;
    int nr_tot = nr + 2 * NGHOST;
    int nth_tot = nth + 2 * NGHOST;
    if (ir >= nr_tot || iph >= nph) return;
    int ncells = nr_tot * nth_tot * nph;

    // North colatitude boundary (ith < NGHOST) and South colatitude boundary (ith >= nth + NGHOST)
    // Zero-gradient outflow/non-reflecting on spherical primitives with v_th = 0, B_th = 0
    for (int g = 0; g < NGHOST; ++g) {
        int ith_dst_n = g;
        int ith_src_n = NGHOST;
        int c_src_n = idx3d(ir, ith_src_n, iph, nr_tot, nth_tot, nph);
        int c_dst_n = idx3d(ir, ith_dst_n, iph, nr_tot, nth_tot, nph);
        double U_s[NVAR], W[NVAR], U_d[NVAR];
        for (int m = 0; m < NVAR; ++m) U_s[m] = d_U[m * ncells + c_src_n];
        cons_to_prim(U_s, W, gamma);
        W[2] = 0.0; // zero normal meridional velocity at high-lat boundary
        W[5] = 0.0;
        W[8] = 0.0;
        prim_to_cons(W, U_d, gamma);
        for (int m = 0; m < NVAR; ++m) d_U[m * ncells + c_dst_n] = U_d[m];

        int ith_dst_s = nth + NGHOST + g;
        int ith_src_s = nth + NGHOST - 1;
        int c_src_s = idx3d(ir, ith_src_s, iph, nr_tot, nth_tot, nph);
        int c_dst_s = idx3d(ir, ith_dst_s, iph, nr_tot, nth_tot, nph);
        for (int m = 0; m < NVAR; ++m) U_s[m] = d_U[m * ncells + c_src_s];
        cons_to_prim(U_s, W, gamma);
        W[2] = 0.0;
        W[5] = 0.0;
        W[8] = 0.0;
        prim_to_cons(W, U_d, gamma);
        for (int m = 0; m < NVAR; ++m) d_U[m * ncells + c_dst_s] = U_d[m];
    }
}

// ----------------------------------------------------------------------------
// 3D Spherical Finite-Volume RHS + RK Stage Update Kernel
//   Uses well-balanced geometric coefficients and Stokes-consistent induction
// ----------------------------------------------------------------------------
__global__ void mhd_rk_stage_kernel(
    const double* __restrict__ d_U0,
    const double* __restrict__ d_U,
    double* __restrict__ d_Uout,
    int nr, int nth, int nph,
    double r_in, double dr,
    double th_min, double dth,
    double dph,
    double gamma,
    double dt,
    double ch,
    int enable_grav,
    int stage // 1: U1 = U0 + dt*L(U0), 2: Unew = 0.5*U0 + 0.5*(U1 + dt*L(U1))
) {
    int iph = blockIdx.x * blockDim.x + threadIdx.x;
    int ith = blockIdx.y * blockDim.y + threadIdx.y + NGHOST;
    int ir  = blockIdx.z * blockDim.z + threadIdx.z + NGHOST;

    int nr_tot = nr + 2 * NGHOST;
    int nth_tot = nth + 2 * NGHOST;
    if (ir >= nr + NGHOST || ith >= nth + NGHOST || iph >= nph) return;

    int ncells = nr_tot * nth_tot * nph;
    int c_ijk = idx3d(ir, ith, iph, nr_tot, nth_tot, nph);

    // Helper lambda to load primitive state at (ir_q, ith_q, iph_q)
    auto get_W = [&](int r_i, int th_i, int ph_i, double W_out[NVAR]) {
        int c = idx3d(r_i, th_i, ph_i, nr_tot, nth_tot, nph);
        double U_loc[NVAR];
        #pragma unroll
        for (int m = 0; m < NVAR; ++m) U_loc[m] = d_U[m * ncells + c];
        cons_to_prim(U_loc, W_out, gamma);
    };

    double W_c[NVAR];
    get_W(ir, ith, iph, W_c);

    // ------------------------------------------------------------------------
    // 1. Radial Fluxes at i-1/2 and i+1/2
    // ------------------------------------------------------------------------
    double W_im2[NVAR], W_im1[NVAR], W_ip1[NVAR], W_ip2[NVAR];
    get_W(ir - 2, ith, iph, W_im2);
    get_W(ir - 1, ith, iph, W_im1);
    get_W(ir + 1, ith, iph, W_ip1);
    get_W(ir + 2, ith, iph, W_ip2);

    double WL_rm[NVAR], WR_rm[NVAR], WL_rp[NVAR], WR_rp[NVAR];
    #pragma unroll
    for (int m = 0; m < NVAR; ++m) {
        double s_im1 = mc_limiter(W_im1[m] - W_im2[m], W_c[m] - W_im1[m]);
        double s_i   = mc_limiter(W_c[m] - W_im1[m], W_ip1[m] - W_c[m]);
        double s_ip1 = mc_limiter(W_ip1[m] - W_c[m], W_ip2[m] - W_ip1[m]);
        WL_rm[m] = W_im1[m] + 0.5 * s_im1;
        WR_rm[m] = W_c[m]   - 0.5 * s_i;
        WL_rp[m] = W_c[m]   + 0.5 * s_i;
        WR_rp[m] = W_ip1[m] - 0.5 * s_ip1;
    }
    double Fr_m[NVAR], Fr_p[NVAR];
    hll_glm_flux(WL_rm, WR_rm, Fr_m, 0, gamma, ch);
    hll_glm_flux(WL_rp, WR_rp, Fr_p, 0, gamma, ch);

    // ------------------------------------------------------------------------
    // 2. Colatitude (theta) Fluxes at j-1/2 and j+1/2
    // ------------------------------------------------------------------------
    double W_jm2[NVAR], W_jm1[NVAR], W_jp1[NVAR], W_jp2[NVAR];
    get_W(ir, ith - 2, iph, W_jm2);
    get_W(ir, ith - 1, iph, W_jm1);
    get_W(ir, ith + 1, iph, W_jp1);
    get_W(ir, ith + 2, iph, W_jp2);

    double WL_tm[NVAR], WR_tm[NVAR], WL_tp[NVAR], WR_tp[NVAR];
    #pragma unroll
    for (int m = 0; m < NVAR; ++m) {
        double s_jm1 = mc_limiter(W_jm1[m] - W_jm2[m], W_c[m] - W_jm1[m]);
        double s_j   = mc_limiter(W_c[m] - W_jm1[m], W_jp1[m] - W_c[m]);
        double s_jp1 = mc_limiter(W_jp1[m] - W_c[m], W_jp2[m] - W_jp1[m]);
        WL_tm[m] = W_jm1[m] + 0.5 * s_jm1;
        WR_tm[m] = W_c[m]   - 0.5 * s_j;
        WL_tp[m] = W_c[m]   + 0.5 * s_j;
        WR_tp[m] = W_jp1[m] - 0.5 * s_jp1;
    }
    double Fth_m[NVAR], Fth_p[NVAR];
    hll_glm_flux(WL_tm, WR_tm, Fth_m, 1, gamma, ch);
    hll_glm_flux(WL_tp, WR_tp, Fth_p, 1, gamma, ch);

    // ------------------------------------------------------------------------
    // 3. Azimuthal (phi) Fluxes at k-1/2 and k+1/2
    // ------------------------------------------------------------------------
    double W_km2[NVAR], W_km1[NVAR], W_kp1[NVAR], W_kp2[NVAR];
    get_W(ir, ith, iph - 2, W_km2);
    get_W(ir, ith, iph - 1, W_km1);
    get_W(ir, ith, iph + 1, W_kp1);
    get_W(ir, ith, iph + 2, W_kp2);

    double WL_pm[NVAR], WR_pm[NVAR], WL_pp[NVAR], WR_pp[NVAR];
    #pragma unroll
    for (int m = 0; m < NVAR; ++m) {
        double s_km1 = mc_limiter(W_km1[m] - W_km2[m], W_c[m] - W_km1[m]);
        double s_k   = mc_limiter(W_c[m] - W_km1[m], W_kp1[m] - W_c[m]);
        double s_kp1 = mc_limiter(W_kp1[m] - W_c[m], W_kp2[m] - W_kp1[m]);
        WL_pm[m] = W_km1[m] + 0.5 * s_km1;
        WR_pm[m] = W_c[m]   - 0.5 * s_k;
        WL_pp[m] = W_c[m]   + 0.5 * s_k;
        WR_pp[m] = W_kp1[m] - 0.5 * s_kp1;
    }
    double Fph_m[NVAR], Fph_p[NVAR];
    hll_glm_flux(WL_pm, WR_pm, Fph_m, 2, gamma, ch);
    hll_glm_flux(WL_pp, WR_pp, Fph_p, 2, gamma, ch);

    // ------------------------------------------------------------------------
    // 4. Exact Spherical Geometry & Well-Balanced Source Terms
    // ------------------------------------------------------------------------
    double r_c = r_in + (ir - NGHOST + 0.5) * dr;
    double r_m = r_c - 0.5 * dr;
    double r_p = r_c + 0.5 * dr;
    double r_m2 = r_m * r_m;
    double r_p2 = r_p * r_p;
    double dV_r = (r_p * r_p2 - r_m * r_m2) / 3.0; // (r_p^3 - r_m^3)/3

    double th_c = th_min + (ith - NGHOST + 0.5) * dth;
    double th_m = th_c - 0.5 * dth;
    double th_p = th_c + 0.5 * dth;
    double sin_m = sin(th_m);
    double sin_p = sin(th_p);
    double sin_c = sin(th_c);
    double cot_c = cos(th_c) / sin_c;
    double d_mu = cos(th_m) - cos(th_p); // integral of sin(th) dth

    // Well-balanced geometric coefficients:
    // Notice (r_p^2 - r_m^2)/dV_r == 2/r_c + O(dr^2), and (sin_p - sin_m)/d_mu == cot(th_c) + O(dth^2)
    double geom_2_over_r = (r_p2 - r_m2) / dV_r;
    double geom_cot_over_r = ((sin_p - sin_m) / d_mu) / r_c;

    double rho = W_c[0];
    double vr  = W_c[1], vth = W_c[2], vph = W_c[3];
    double br  = W_c[4], bth = W_c[5], bph = W_c[6];
    double p   = W_c[7];
    double b2  = br * br + bth * bth + bph * bph;
    double ptot = p + 0.5 * b2;

    double divF[NVAR];
    #pragma unroll
    for (int m = 0; m < NVAR; ++m) {
        if (m == 5 || m == 6) {
            // Stokes-consistent radial curl induction term: (1/r) d/dr (r F_r)
            double r_avg = 0.5 * (r_p2 - r_m2);
            divF[m] = (r_p * Fr_p[m] - r_m * Fr_m[m]) / r_avg
                    + ((m == 5) ? ((sin_p * Fth_p[m] - sin_m * Fth_m[m]) / (r_c * d_mu))
                                : ((Fth_p[m] - Fth_m[m]) / (r_c * dth)))
                    + (Fph_p[m] - Fph_m[m]) / (r_c * sin_c * dph);
        } else if (m == 8) {
            // GLM psi flux: c_h^2 div(B)
            divF[8] = (r_p2 * Fr_p[8] - r_m2 * Fr_m[8]) / dV_r
                    + (sin_p * Fth_p[8] - sin_m * Fth_m[8]) / (r_c * d_mu)
                    + (Fph_p[8] - Fph_m[8]) / (r_c * sin_c * dph);
        } else {
            divF[m] = (r_p2 * Fr_p[m] - r_m2 * Fr_m[m]) / dV_r
                    + (sin_p * Fth_p[m] - sin_m * Fth_m[m]) / (r_c * d_mu)
                    + (Fph_p[m] - Fph_m[m]) / (r_c * sin_c * dph);
        }
    }

    // Discrete divergence of B for Powell 8-wave source terms
    double br_face_p = 0.5 * (WL_rp[4] + WR_rp[4]);
    double br_face_m = 0.5 * (WL_rm[4] + WR_rm[4]);
    double bth_face_p = 0.5 * (WL_tp[5] + WR_tp[5]);
    double bth_face_m = 0.5 * (WL_tm[5] + WR_tm[5]);
    double bph_face_p = 0.5 * (WL_pp[6] + WR_pp[6]);
    double bph_face_m = 0.5 * (WL_pm[6] + WR_pm[6]);
    double divB = (r_p2 * br_face_p - r_m2 * br_face_m) / dV_r
                + (sin_p * bth_face_p - sin_m * bth_face_m) / (r_c * d_mu)
                + (bph_face_p - bph_face_m) / (r_c * sin_c * dph);

    double S[NVAR] = {0.0};
    S[1] = geom_2_over_r * ptot + (rho * (vth * vth + vph * vph) - (bth * bth + bph * bph)) / r_c;
    S[2] = geom_cot_over_r * ptot + (rho * (vph * vph * cot_c - vr * vth) - (bph * bph * cot_c - br * bth)) / r_c;
    S[3] = -(rho * vph * (vr + vth * cot_c) - bph * (br + bth * cot_c)) / r_c;
    // Note: Because Bth and Bph use the exact Stokes curl form above, their geometric induction terms are already exact!

    // Solar gravity source term
    if (enable_grav) {
        double g_r = -GM_SUN_CODE / (r_c * r_c);
        S[1] += rho * g_r;
        S[7] += rho * vr * g_r;
    }

    // Powell 8-wave source term
    double vdotb = vr * br + vth * bth + vph * bph;
    S[1] -= divB * br;
    S[2] -= divB * bth;
    S[3] -= divB * bph;
    S[4] -= divB * vr;
    S[5] -= divB * vth;
    S[6] -= divB * vph;
    S[7] -= divB * vdotb;

    // Update conservative state with SSPRK2 stage
    double U_new[NVAR];
    #pragma unroll
    for (int m = 0; m < NVAR; ++m) {
        double u_curr = d_U[m * ncells + c_ijk];
        double rhs = -divF[m] + S[m];
        if (stage == 1) {
            U_new[m] = u_curr + dt * rhs;
        } else {
            double u_0 = d_U0[m * ncells + c_ijk];
            U_new[m] = 0.5 * u_0 + 0.5 * (u_curr + dt * rhs);
        }
    }

    // Parabolic damping of GLM potential psi (Dedner et al. 2002; Mignone & Tzeferacos 2010)
    U_new[8] *= exp(-0.25);

    // Enforce positivity of density and thermal pressure
    double W_check[NVAR];
    cons_to_prim(U_new, W_check, gamma);
    prim_to_cons(W_check, U_new, gamma);

    #pragma unroll
    for (int m = 0; m < NVAR; ++m) {
        d_Uout[m * ncells + c_ijk] = U_new[m];
    }
}

// ----------------------------------------------------------------------------
// Kernel to initialize domain with radially expanded inner boundary state
// ----------------------------------------------------------------------------
__global__ void init_domain_from_inner_kernel(
    double* __restrict__ d_U, int nr, int nth, int nph, double r_in, double dr, double gamma
) {
    int iph = blockIdx.x * blockDim.x + threadIdx.x;
    int ith = blockIdx.y * blockDim.y + threadIdx.y;
    int ir  = blockIdx.z * blockDim.z + threadIdx.z + NGHOST;

    int nr_tot = nr + 2 * NGHOST;
    int nth_tot = nth + 2 * NGHOST;
    if (ir >= nr_tot || ith >= nth_tot || iph >= nph) return;

    int ncells = nr_tot * nth_tot * nph;
    int c_in = idx3d(NGHOST - 1, ith, iph, nr_tot, nth_tot, nph);
    double r_src = r_in - 0.5 * dr;
    double r_dst = r_in + (ir - NGHOST + 0.5) * dr;
    double ratio = r_src / r_dst;
    double ratio2 = ratio * ratio;

    double U_in[NVAR], W[NVAR];
    for (int m = 0; m < NVAR; ++m) U_in[m] = d_U[m * ncells + c_in];
    cons_to_prim(U_in, W, gamma);

    W[0] *= ratio2;
    W[4] *= ratio2;
    W[6] *= ratio; // Parker B_phi scales as 1/r
    W[7] *= pow(ratio2, gamma);
    W[8] = 0.0;

    double U_out[NVAR];
    prim_to_cons(W, U_out, gamma);
    int c_dst = idx3d(ir, ith, iph, nr_tot, nth_tot, nph);
    for (int m = 0; m < NVAR; ++m) d_U[m * ncells + c_dst] = U_out[m];
}

// ----------------------------------------------------------------------------
// Host Trilinear Interpolation for Spacecraft & Comet Probes
// ----------------------------------------------------------------------------
void sample_probe_trilinear(
    const std::vector<double>& h_U,
    int nr, int nth, int nph,
    double r_in, double dr,
    double th_min, double dth,
    double dph,
    double gamma,
    double r_p, double th_p, double ph_p,
    double W_out[NVAR]
) {
    int nr_tot = nr + 2 * NGHOST;
    int nth_tot = nth + 2 * NGHOST;
    int ncells = nr_tot * nth_tot * nph;

    double fr = (r_p - (r_in + 0.5 * dr)) / dr + NGHOST;
    int ir0 = std::max(NGHOST, std::min((int)std::floor(fr), nr + NGHOST - 2));
    int ir1 = ir0 + 1;
    double wr = std::max(0.0, std::min(fr - ir0, 1.0));

    double fth = (th_p - (th_min + 0.5 * dth)) / dth + NGHOST;
    int ith0 = std::max(NGHOST, std::min((int)std::floor(fth), nth + NGHOST - 2));
    int ith1 = ith0 + 1;
    double wth = std::max(0.0, std::min(fth - ith0, 1.0));

    double fph = (ph_p - 0.5 * dph) / dph;
    int iph0 = ((int)std::floor(fph) % nph + nph) % nph;
    int iph1 = (iph0 + 1) % nph;
    double wph = fph - std::floor(fph);

    for (int m = 0; m < NVAR; ++m) W_out[m] = 0.0;

    for (int dr_i = 0; dr_i <= 1; ++dr_i) {
        double wt_r = (dr_i == 0) ? (1.0 - wr) : wr;
        int ir = (dr_i == 0) ? ir0 : ir1;
        for (int dth_i = 0; dth_i <= 1; ++dth_i) {
            double wt_th = (dth_i == 0) ? (1.0 - wth) : wth;
            int ith = (dth_i == 0) ? ith0 : ith1;
            for (int dph_i = 0; dph_i <= 1; ++dph_i) {
                double wt_ph = (dph_i == 0) ? (1.0 - wph) : wph;
                int iph = (dph_i == 0) ? iph0 : iph1;
                double weight = wt_r * wt_th * wt_ph;
                int cell = idx3d(ir, ith, iph, nr_tot, nth_tot, nph);
                double U_loc[NVAR], W_loc[NVAR];
                for (int m = 0; m < NVAR; ++m) U_loc[m] = h_U[m * ncells + cell];
                cons_to_prim(U_loc, W_loc, gamma);
                for (int m = 0; m < NVAR; ++m) W_out[m] += weight * W_loc[m];
            }
        }
    }
}

// ----------------------------------------------------------------------------
// Mode 1: 1D Brio & Wu (1988) MHD Shock Tube Benchmark
// ----------------------------------------------------------------------------
void run_brio_wu_benchmark(const SimConfig& cfg) {
    printf("Running 1D Brio & Wu (1988) MHD Shock Tube Benchmark...\n");
    int resolutions[3] = {400, 800, 1600};
    std::vector<std::vector<double>> rho_results(3);

    for (int r_idx = 0; r_idx < 3; ++r_idx) {
        int nx = resolutions[r_idx];
        int nx_tot = nx + 2 * NGHOST;
        double dx = 1.0 / nx;
        double gamma_bw = 2.0;
        double t_end = 0.1;
        double t = 0.0;

        std::vector<double> U(nx_tot * NVAR, 0.0);
        std::vector<double> U1(nx_tot * NVAR, 0.0);

        for (int i = 0; i < nx_tot; ++i) {
            double x = (i - NGHOST + 0.5) * dx;
            double W[NVAR] = {0.0};
            if (x < 0.5) {
                W[0] = 1.0;   W[4] = 0.75; W[5] = 1.0;  W[7] = 1.0;   W[9] = 1.0e-3;
            } else {
                W[0] = 0.125; W[4] = 0.75; W[5] = -1.0; W[7] = 0.1;   W[9] = 5.0e-4;
            }
            prim_to_cons(W, &U[i * NVAR], gamma_bw);
        }

        auto apply_bw_bc = [&](std::vector<double>& arr) {
            for (int g = 0; g < NGHOST; ++g) {
                for (int m = 0; m < NVAR; ++m) {
                    arr[g * NVAR + m] = arr[NGHOST * NVAR + m];
                    arr[(nx + NGHOST + g) * NVAR + m] = arr[(nx + NGHOST - 1) * NVAR + m];
                }
            }
        };

        auto step_1d = [&](const std::vector<double>& Uin, std::vector<double>& Uout, double dt, double ch, int stage) {
            std::vector<double> W(nx_tot * NVAR);
            for (int i = 0; i < nx_tot; ++i) cons_to_prim(&Uin[i * NVAR], &W[i * NVAR], gamma_bw);

            std::vector<double> F((nx + 1) * NVAR, 0.0);
            for (int f = 0; f <= nx; ++f) {
                int iL = f + NGHOST - 1;
                int iR = f + NGHOST;
                double WL[NVAR], WR[NVAR];
                for (int m = 0; m < NVAR; ++m) {
                    double sL = mc_limiter(W[iL * NVAR + m] - W[(iL - 1) * NVAR + m], W[iR * NVAR + m] - W[iL * NVAR + m]);
                    double sR = mc_limiter(W[iR * NVAR + m] - W[iL * NVAR + m], W[(iR + 1) * NVAR + m] - W[iR * NVAR + m]);
                    WL[m] = W[iL * NVAR + m] + 0.5 * sL;
                    WR[m] = W[iR * NVAR + m] - 0.5 * sR;
                }
                hll_glm_flux(WL, WR, &F[f * NVAR], 0, gamma_bw, ch);
            }

            for (int i = NGHOST; i < nx + NGHOST; ++i) {
                int f_m = i - NGHOST;
                int f_p = f_m + 1;
                for (int m = 0; m < NVAR; ++m) {
                    double rhs = -(F[f_p * NVAR + m] - F[f_m * NVAR + m]) / dx;
                    if (stage == 1) {
                        Uout[i * NVAR + m] = Uin[i * NVAR + m] + dt * rhs;
                    } else {
                        Uout[i * NVAR + m] = 0.5 * U[i * NVAR + m] + 0.5 * (Uin[i * NVAR + m] + dt * rhs);
                    }
                }
            }
        };

        while (t < t_end) {
            double max_speed = 3.5;
            double dt = 0.4 * dx / max_speed;
            if (t + dt > t_end) dt = t_end - t;
            apply_bw_bc(U);
            step_1d(U, U1, dt, max_speed, 1);
            apply_bw_bc(U1);
            step_1d(U1, U, dt, max_speed, 2);
            t += dt;
        }

        rho_results[r_idx].resize(nx);
        for (int i = 0; i < nx; ++i) {
            rho_results[r_idx][i] = U[(i + NGHOST) * NVAR + 0];
        }

        if (nx == 800 || nx == 1600) {
            std::ofstream fout(cfg.out_prefix + "_brio_wu_" + std::to_string(nx) + ".tsv");
            fout << "x\trho\tvx\tvy\tBx\tBy\tp\tf_hi\n";
            for (int i = 0; i < nx; ++i) {
                double W[NVAR];
                cons_to_prim(&U[(i + NGHOST) * NVAR], W, gamma_bw);
                fout << std::fixed << std::setprecision(6)
                     << (i + 0.5) * dx << "\t" << W[0] << "\t" << W[1] << "\t" << W[2] << "\t"
                     << W[4] << "\t" << W[5] << "\t" << W[7] << "\t" << W[9] << "\n";
            }
        }
    }

    // Compute L1 self-convergence of N=400 and N=800 against N=1600
    double l1_400 = 0.0, l1_800 = 0.0;
    for (int i = 0; i < 400; ++i) {
        double ref = 0.25 * (rho_results[2][4*i] + rho_results[2][4*i+1] + rho_results[2][4*i+2] + rho_results[2][4*i+3]);
        l1_400 += std::fabs(rho_results[0][i] - ref) / 400.0;
    }
    for (int i = 0; i < 800; ++i) {
        double ref = 0.5 * (rho_results[2][2*i] + rho_results[2][2*i+1]);
        l1_800 += std::fabs(rho_results[1][i] - ref) / 800.0;
    }
    printf("Brio-Wu L1(400 vs 1600) = %.6f, L1(800 vs 1600) = %.6f, Ratio = %.3f\n",
           l1_400, l1_800, l1_400 / l1_800);

    std::ofstream fjson(cfg.out_prefix + "_brio_wu_metrics.json");
    fjson << "{\n"
          << "  \"l1_rho_400_vs_1600\": " << l1_400 << ",\n"
          << "  \"l1_rho_800_vs_1600\": " << l1_800 << ",\n"
          << "  \"convergence_ratio\": " << (l1_400 / l1_800) << "\n"
          << "}\n";
}

// ----------------------------------------------------------------------------
// Main 3D Spherical Simulation Driver (Parker Steady, Tilted CIR, Solar Wind)
// ----------------------------------------------------------------------------
void run_3d_spherical_simulation(const SimConfig& cfg) {
    int nr = cfg.nr, nth = cfg.nth, nph = cfg.nph;
    int nr_tot = nr + 2 * NGHOST;
    int nth_tot = nth + 2 * NGHOST;
    int ncells = nr_tot * nth_tot * nph;

    double dr = (cfg.r_out - cfg.r_in) / nr;
    double th_min = (90.0 - cfg.lat_max_deg) * DEG2RAD;
    double th_max = (90.0 + cfg.lat_max_deg) * DEG2RAD;
    double dth = (th_max - th_min) / nth;
    double dph = (2.0 * PI) / nph;

    size_t state_bytes = (size_t)NVAR * ncells * sizeof(double);
    printf("Initializing 3D Spherical MHD Solver [%s]: Grid (%d x %d x %d), Memory = %.2f MB per state buffer\n",
           cfg.mode.c_str(), nr, nth, nph, state_bytes / (1024.0 * 1024.0));

    double *d_U = nullptr, *d_U1 = nullptr;
    CUDA_CHECK(cudaMalloc(&d_U, state_bytes));
    CUDA_CHECK(cudaMalloc(&d_U1, state_bytes));

    // Load boundary map if solar_wind mode
    float* d_bc_map = nullptr;
    int bc_type = 0;
    if (cfg.mode == "parker_steady") bc_type = 0;
    else if (cfg.mode == "tilted_cir") bc_type = 1;
    else bc_type = 2;

    if (bc_type == 2) {
        std::vector<float> h_bc(4 * 90 * 180, 0.0f);
        std::ifstream fin(cfg.bc_file, std::ios::binary);
        if (!fin) {
            fprintf(stderr, "Failed to open boundary file: %s\n", cfg.bc_file.c_str());
            exit(EXIT_FAILURE);
        }
        fin.read(reinterpret_cast<char*>(h_bc.data()), h_bc.size() * sizeof(float));
        CUDA_CHECK(cudaMalloc(&d_bc_map, h_bc.size() * sizeof(float)));
        CUDA_CHECK(cudaMemcpy(d_bc_map, h_bc.data(), h_bc.size() * sizeof(float), cudaMemcpyHostToDevice));
    }

    // Load CMEs if enabled
    CMEEvent* d_cmes = nullptr;
    int n_cmes = 0;
    if (cfg.enable_cmes && bc_type == 2) {
        std::ifstream fcme(cfg.cme_file);
        if (fcme) {
            fcme >> n_cmes;
            std::vector<CMEEvent> h_cmes(n_cmes);
            for (int i = 0; i < n_cmes; ++i) {
                fcme >> h_cmes[i].mjd_launch >> h_cmes[i].lat_deg >> h_cmes[i].lon_hci_deg
                     >> h_cmes[i].half_width_deg >> h_cmes[i].v_kms;
            }
            CUDA_CHECK(cudaMalloc(&d_cmes, n_cmes * sizeof(CMEEvent)));
            CUDA_CHECK(cudaMemcpy(d_cmes, h_cmes.data(), n_cmes * sizeof(CMEEvent), cudaMemcpyHostToDevice));
        }
    }

    // Load probe trajectories if solar_wind mode
    constexpr int NT_TRAJ = 2449;
    constexpr int NPROBES = 5;
    std::vector<double> h_traj;
    if (bc_type == 2) {
        h_traj.resize(NT_TRAJ * NPROBES * 7);
        std::ifstream ftr(cfg.traj_file, std::ios::binary);
        if (!ftr) {
            fprintf(stderr, "Failed to open trajectory file: %s\n", cfg.traj_file.c_str());
            exit(EXIT_FAILURE);
        }
        ftr.read(reinterpret_cast<char*>(h_traj.data()), h_traj.size() * sizeof(double));
    }

    dim3 block_bc(16, 16);
    dim3 grid_bc((nth_tot + 15) / 16, (nph + 15) / 16);
    dim3 grid_lat((nr_tot + 15) / 16, (nph + 15) / 16);

    dim3 block_3d(16, 4, 4);
    dim3 grid_3d((nph + 15) / 16, (nth + 3) / 4, (nr + 3) / 4);
    dim3 grid_init((nph + 15) / 16, (nth_tot + 3) / 4, (nr + NGHOST + 3) / 4);

    // Initialize inner ghost cells and radially expand across domain
    double mjd_init = cfg.mjd_start;
    apply_boundary_conditions_kernel<<<grid_bc, block_bc>>>(
        d_U, d_bc_map, d_cmes, n_cmes, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
        cfg.gamma, 0.0, mjd_init, cfg.mjd_ref, cfg.phase_ref_deg, bc_type, cfg.enable_mag, 0
    );
    init_domain_from_inner_kernel<<<grid_init, block_3d>>>(
        d_U, nr, nth, nph, cfg.r_in, dr, cfg.gamma
    );
    apply_boundary_conditions_kernel<<<grid_bc, block_bc>>>(
        d_U, d_bc_map, d_cmes, n_cmes, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
        cfg.gamma, 0.0, mjd_init, cfg.mjd_ref, cfg.phase_ref_deg, bc_type, cfg.enable_mag, 0
    );
    apply_lat_boundary_kernel<<<grid_lat, block_bc>>>(d_U, nr, nth, nph, cfg.gamma);
    CUDA_CHECK(cudaDeviceSynchronize());

    // Minimum cell size dx_min at r = r_in, th = th_min
    double dx_r = dr;
    double dx_th = cfg.r_in * dth;
    double dx_ph = cfg.r_in * sin(th_min) * dph;
    double h_min = std::min({dx_r, dx_th, dx_ph});
    double v_max_code = 9.5; // ~950 km/s max fast magnetosonic speed
    double dt_code = cfg.cfl * h_min / v_max_code;
    double ch_glm = 4.0;     // decoupled GLM wave speed in code units (400 km/s)

    auto t_wall_start = std::chrono::high_resolution_clock::now();

    // ------------------------------------------------------------------------
    // Phase A: Relaxation to Quasi-Steady State (for all 3D modes)
    // ------------------------------------------------------------------------
    double relax_code_time = cfg.relax_days / CODE_T0_DAYS;
    int n_relax_steps = (int)std::ceil(relax_code_time / dt_code);
    printf("Phase A: Relaxing 3D heliosphere for %.1f days (%d RK2 steps, dt = %.5f d)...\n",
           cfg.relax_days, n_relax_steps, dt_code * CODE_T0_DAYS);

    double t_code = 0.0;
    for (int step = 0; step < n_relax_steps; ++step) {
        double t_bc = (bc_type == 1) ? t_code : 0.0;
        // Stage 1
        apply_boundary_conditions_kernel<<<grid_bc, block_bc>>>(
            d_U, d_bc_map, d_cmes, n_cmes, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, t_bc, mjd_init, cfg.mjd_ref, cfg.phase_ref_deg, bc_type, cfg.enable_mag, 0
        );
        apply_lat_boundary_kernel<<<grid_lat, block_bc>>>(d_U, nr, nth, nph, cfg.gamma);
        mhd_rk_stage_kernel<<<grid_3d, block_3d>>>(
            d_U, d_U, d_U1, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, dt_code, ch_glm, cfg.enable_grav, 1
        );

        // Stage 2
        apply_boundary_conditions_kernel<<<grid_bc, block_bc>>>(
            d_U1, d_bc_map, d_cmes, n_cmes, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, t_bc + dt_code, mjd_init, cfg.mjd_ref, cfg.phase_ref_deg, bc_type, cfg.enable_mag, 0
        );
        apply_lat_boundary_kernel<<<grid_lat, block_bc>>>(d_U1, nr, nth, nph, cfg.gamma);
        mhd_rk_stage_kernel<<<grid_3d, block_3d>>>(
            d_U, d_U1, d_U, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, dt_code, ch_glm, cfg.enable_grav, 2
        );
        t_code += dt_code;
    }
    CUDA_CHECK(cudaDeviceSynchronize());

    std::vector<double> h_U((size_t)NVAR * ncells);

    // If Parker steady or Tilted CIR benchmark, export radial/azimuthal profiles & diagnostics and return
    if (bc_type == 0 || bc_type == 1) {
        CUDA_CHECK(cudaMemcpy(h_U.data(), d_U, state_bytes, cudaMemcpyDeviceToHost));
        auto t_wall_end = std::chrono::high_resolution_clock::now();
        double elapsed_s = std::chrono::duration<double>(t_wall_end - t_wall_start).count();
        printf("Completed %s in %.2f s wall time.\n", cfg.mode.c_str(), elapsed_s);

        int ith_eq = NGHOST + nth / 2;
        if (bc_type == 0) {
            // Export equatorial radial profile & compute exact conservation errors
            std::ofstream fout(cfg.out_prefix + "_parker_profile.tsv");
            fout << "r_au\tn_cm3\tvr_kms\tvph_kms\tBr_nT\tBph_nT\tT_K\tf_hi\tmass_flux_rel_err\tbr_flux_rel_err\n";

            double c_ref = idx3d(NGHOST, ith_eq, 0, nr_tot, nth_tot, nph);
            double U_ref[NVAR], W_ref[NVAR];
            for (int m = 0; m < NVAR; ++m) U_ref[m] = h_U[m * ncells + (int)c_ref];
            cons_to_prim(U_ref, W_ref, cfg.gamma);
            double r0 = cfg.r_in + 0.5 * dr;
            double mflux0 = r0 * r0 * W_ref[0] * W_ref[1];
            double bflux0 = r0 * r0 * W_ref[4];

            double sum_m_err = 0.0, sum_b_err = 0.0, sum_fhi_err = 0.0;
            for (int ir = NGHOST; ir < nr + NGHOST; ++ir) {
                double r = cfg.r_in + (ir - NGHOST + 0.5) * dr;
                int c = idx3d(ir, ith_eq, 0, nr_tot, nth_tot, nph);
                double U_loc[NVAR], W[NVAR];
                for (int m = 0; m < NVAR; ++m) U_loc[m] = h_U[m * ncells + c];
                cons_to_prim(U_loc, W, cfg.gamma);
                double m_err = std::fabs(r * r * W[0] * W[1] - mflux0) / mflux0;
                double b_err = ( std::fabs(bflux0) > 1e-8 ) ? std::fabs(r * r * W[4] - bflux0) / std::fabs(bflux0) : 0.0;
                double f_err = std::fabs(W[9] - 7.646e-4) / 7.646e-4;
                sum_m_err += m_err / nr;
                sum_b_err += b_err / nr;
                sum_fhi_err += f_err / nr;

                fout << std::fixed << std::setprecision(6)
                     << r << "\t" << W[0] << "\t" << W[1] * CODE_V0_KMS << "\t" << W[3] * CODE_V0_KMS << "\t"
                     << W[4] * CODE_B0_NT << "\t" << W[6] * CODE_B0_NT << "\t" << (W[7] / W[0]) * CODE_T_SCALE_K << "\t"
                     << W[9] << "\t" << m_err << "\t" << b_err << "\n";
            }
            printf("Parker Steady Errors: mean |d(r^2 rho vr)| = %.4e, mean |d(r^2 Br)| = %.4e, mean |df_hi| = %.4e\n",
                   sum_m_err, sum_b_err, sum_fhi_err);
            std::ofstream fj(cfg.out_prefix + "_parker_metrics.json");
            fj << "{\n"
               << "  \"nr\": " << nr << ", \"nth\": " << nth << ", \"nph\": " << nph << ",\n"
               << "  \"wall_time_s\": " << elapsed_s << ",\n"
               << "  \"mean_mass_flux_rel_err\": " << sum_m_err << ",\n"
               << "  \"mean_br_flux_rel_err\": " << sum_b_err << ",\n"
               << "  \"mean_fhi_rel_err\": " << sum_fhi_err << "\n"
               << "}\n";
        } else {
            // Tilted CIR benchmark: Export azimuthal profiles at r = 1.0 AU and r = 1.87 AU (3I/ATLAS distance)
            // and 2D equatorial slice
            std::ofstream fout(cfg.out_prefix + "_cir_azimuthal.tsv");
            fout << "phi_deg\tn_1au\tvr_1au\tvph_1au\tBmag_1au\tT_1au\tfhi_1au\tn_187au\tvr_187au\tvph_187au\tBmag_187au\tT_187au\tfhi_187au\n";
            double th_eq = 0.5 * PI;
            for (int iph = 0; iph < nph; ++iph) {
                double ph = (iph + 0.5) * dph;
                double W1[NVAR], W2[NVAR];
                sample_probe_trilinear(h_U, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph, cfg.gamma, 1.00, th_eq, ph, W1);
                sample_probe_trilinear(h_U, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph, cfg.gamma, 1.873, th_eq, ph, W2);
                double B1 = std::sqrt(W1[4]*W1[4] + W1[5]*W1[5] + W1[6]*W1[6]) * CODE_B0_NT;
                double B2 = std::sqrt(W2[4]*W2[4] + W2[5]*W2[5] + W2[6]*W2[6]) * CODE_B0_NT;
                fout << std::fixed << std::setprecision(5)
                     << ph * RAD2DEG << "\t"
                     << W1[0] << "\t" << W1[1] * CODE_V0_KMS << "\t" << W1[3] * CODE_V0_KMS << "\t" << B1 << "\t" << (W1[7]/W1[0])*CODE_T_SCALE_K << "\t" << W1[9] << "\t"
                     << W2[0] << "\t" << W2[1] * CODE_V0_KMS << "\t" << W2[3] * CODE_V0_KMS << "\t" << B2 << "\t" << (W2[7]/W2[0])*CODE_T_SCALE_K << "\t" << W2[9] << "\n";
            }
        }
        CUDA_CHECK(cudaFree(d_U));
        CUDA_CHECK(cudaFree(d_U1));
        return;
    }

    // ------------------------------------------------------------------------
    // Phase B: Time-Dependent Evolution (MJD_start = 60998.0 to MJD_end = 61015.0)
    // ------------------------------------------------------------------------
    double total_days = cfg.mjd_end - cfg.mjd_start;
    double dt_days = dt_code * CODE_T0_DAYS;
    int n_evol_steps = (int)std::ceil(total_days / dt_days);
    dt_days = total_days / n_evol_steps;
    dt_code = dt_days / CODE_T0_DAYS;

    printf("Phase B: Time-dependent evolution from MJD %.1f to %.1f (%d RK2 steps, dt = %.4f min)...\n",
           cfg.mjd_start, cfg.mjd_end, n_evol_steps, dt_days * 1440.0);

    // Prepare probe time series output table
    std::ofstream fprobes(cfg.out_prefix + "_probes.tsv");
    fprobes << "mjd_utc\tprobe\tr_au\tlat_hci_deg\tlon_hci_deg\tn_cm3\tvr_kms\tvth_kms\tvph_kms\tvmag_kms\tvrel_comet_kms\t"
            << "flux_helio_cm2s\tflux_rel_cm2s\tBr_nT\tBth_nT\tBph_nT\tBmag_nT\tT_K\tf_hi\tflux_hi_helio_cm2s\tflux_hi_rel_cm2s\n";

    const char* probe_names[NPROBES] = {"comet", "stereo_a", "solar_orbiter", "wind", "ace"};
    int next_traj_idx = 0;
    int slice_idx = 0;
    double next_slice_mjd = 61006.0; // Save 2D equatorial slices from Nov 27 to Dec 06 every 2.4 hours (0.1 day)

    for (int step = 0; step <= n_evol_steps; ++step) {
        double mjd_curr = cfg.mjd_start + step * dt_days;

        // Check if we reached the next 10-minute trajectory sample or 2D slice output
        bool need_host_copy = false;
        if (next_traj_idx < NT_TRAJ && mjd_curr >= h_traj[next_traj_idx * NPROBES * 7 + 0] - 1e-7) {
            need_host_copy = true;
        }
        if (cfg.save_slices && mjd_curr >= next_slice_mjd - 1e-7) {
            need_host_copy = true;
        }

        if (need_host_copy) {
            CUDA_CHECK(cudaMemcpy(h_U.data(), d_U, state_bytes, cudaMemcpyDeviceToHost));

            while (next_traj_idx < NT_TRAJ && mjd_curr >= h_traj[next_traj_idx * NPROBES * 7 + 0] - 1e-7) {
                double t_sample = h_traj[next_traj_idx * NPROBES * 7 + 0];
                for (int p = 0; p < NPROBES; ++p) {
                    const double* tr = &h_traj[(next_traj_idx * NPROBES + p) * 7];
                    double r_p = tr[1];
                    double th_p = tr[2];
                    double ph_p = tr[3];
                    double vr_body = tr[4];
                    double vth_body = tr[5];
                    double vph_body = tr[6];

                    double W[NVAR];
                    sample_probe_trilinear(h_U, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph, cfg.gamma, r_p, th_p, ph_p, W);

                    double n_p = W[0];
                    double vr_sw = W[1] * CODE_V0_KMS;
                    double vth_sw = W[2] * CODE_V0_KMS;
                    double vph_sw = W[3] * CODE_V0_KMS;
                    double vmag_sw = std::sqrt(vr_sw * vr_sw + vth_sw * vth_sw + vph_sw * vph_sw);
                    double vrel = std::sqrt(
                        (vr_sw - vr_body) * (vr_sw - vr_body) +
                        (vth_sw - vth_body) * (vth_sw - vth_body) +
                        (vph_sw - vph_body) * (vph_sw - vph_body)
                    );
                    double flux_helio = n_p * vmag_sw * 1.0e5;
                    double flux_rel = n_p * vrel * 1.0e5;
                    double br_nT = W[4] * CODE_B0_NT;
                    double bth_nT = W[5] * CODE_B0_NT;
                    double bph_nT = W[6] * CODE_B0_NT;
                    double bmag_nT = std::sqrt(br_nT * br_nT + bth_nT * bth_nT + bph_nT * bph_nT);
                    double T_K = (W[7] / W[0]) * CODE_T_SCALE_K;
                    double f_hi = W[9];

                    fprobes << std::fixed << std::setprecision(6)
                            << t_sample << "\t" << probe_names[p] << "\t"
                            << r_p << "\t" << (90.0 - th_p * RAD2DEG) << "\t" << (ph_p * RAD2DEG) << "\t"
                            << n_p << "\t" << vr_sw << "\t" << vth_sw << "\t" << vph_sw << "\t"
                            << vmag_sw << "\t" << vrel << "\t"
                            << std::scientific << std::setprecision(6)
                            << flux_helio << "\t" << flux_rel << "\t"
                            << std::fixed << std::setprecision(4)
                            << br_nT << "\t" << bth_nT << "\t" << bph_nT << "\t" << bmag_nT << "\t"
                            << std::Fixed << std::setprecision(1) << T_K << "\t"
                            << std::scientific << std::setprecision(5)
                            << f_hi << "\t" << (flux_helio * f_hi) << "\t" << (flux_rel * f_hi) << "\n";
                }
                next_traj_idx++;
            }

            if (cfg.save_slices && mjd_curr >= next_slice_mjd - 1e-7) {
                // Save 2D slice at comet latitude (-6.45 deg, th = 96.45 deg) of (n_p, vmag, flux_p, Bmag, f_hi)
                // as float32 binary: shape (4, nr, nph)
                double th_comet = (90.0 - (-6.455)) * DEG2RAD;
                std::vector<float> slice_buf(4 * nr * nph);
                for (int ir = 0; ir < nr; ++ir) {
                    double r_val = cfg.r_in + (ir + 0.5) * dr;
                    for (int iph = 0; iph < nph; ++iph) {
                        double ph_val = (iph + 0.5) * dph;
                        double W[NVAR];
                        sample_probe_trilinear(h_U, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph, cfg.gamma, r_val, th_comet, ph_val, W);
                        double vmag = std::sqrt(W[1]*W[1] + W[2]*W[2] + W[3]*W[3]) * CODE_V0_KMS;
                        double flux = W[0] * vmag * 1.0e5;
                        int idx2d = ir * nph + iph;
                        slice_buf[0 * nr * nph + idx2d] = (float)W[0];
                        slice_buf[1 * nr * nph + idx2d] = (float)vmag;
                        slice_buf[2 * nr * nph + idx2d] = (float)flux;
                        slice_buf[3 * nr * nph + idx2d] = (float)W[9];
                    }
                }
                char sname[512];
                snprintf(sname, sizeof(sname), "%s_slice_%03d.bin", cfg.out_prefix.c_str(), slice_idx);
                std::ofstream fsl(sname, std::ios::binary);
                fsl.write(reinterpret_cast<const char*>(&mjd_curr), sizeof(double));
                fsl.write(reinterpret_cast<const char*>(slice_buf.data()), slice_buf.size() * sizeof(float));
                slice_idx++;
                next_slice_mjd += 0.125; // Every 3 hours (8 frames per day)
            }
        }

        if (step == n_evol_steps) break;

        // Advance one SSPRK2 step
        apply_boundary_conditions_kernel<<<grid_bc, block_bc>>>(
            d_U, d_bc_map, d_cmes, n_cmes, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, 0.0, mjd_curr, cfg.mjd_ref, cfg.phase_ref_deg, bc_type, cfg.enable_mag, cfg.enable_cmes
        );
        apply_lat_boundary_kernel<<<grid_lat, block_bc>>>(d_U, nr, nth, nph, cfg.gamma);
        mhd_rk_stage_kernel<<<grid_3d, block_3d>>>(
            d_U, d_U, d_U1, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, dt_code, ch_glm, cfg.enable_grav, 1
        );

        apply_boundary_conditions_kernel<<<grid_bc, block_bc>>>(
            d_U1, d_bc_map, d_cmes, n_cmes, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, 0.0, mjd_curr + dt_days, cfg.mjd_ref, cfg.phase_ref_deg, bc_type, cfg.enable_mag, cfg.enable_cmes
        );
        apply_lat_boundary_kernel<<<grid_lat, block_bc>>>(d_U1, nr, nth, nph, cfg.gamma);
        mhd_rk_stage_kernel<<<grid_3d, block_3d>>>(
            d_U, d_U1, d_U, nr, nth, nph, cfg.r_in, dr, th_min, dth, dph,
            cfg.gamma, dt_code, ch_glm, cfg.enable_grav, 2
        );
    }

    CUDA_CHECK(cudaDeviceSynchronize());
    auto t_wall_end = std::chrono::high_resolution_clock::now();
    double elapsed_s = std::chrono::duration<double>(t_wall_end - t_wall_start).count();
    printf("Completed 3D Solar Wind MHD Run [%s] in %.2f s wall time (%d slices saved).\n",
           cfg.out_prefix.c_str(), elapsed_s, slice_idx);

    // Compute final-state dimensionless magnetic divergence diagnostic h|divB|/|B|
    CUDA_CHECK(cudaMemcpy(h_U.data(), d_U, state_bytes, cudaMemcpyDeviceToHost));
    double num_divb = 0.0, den_b = 0.0;
    for (int ir = NGHOST + 2; ir < nr + NGHOST - 2; ++ir) {
        double r_c = cfg.r_in + (ir - NGHOST + 0.5) * dr;
        if (r_c < 0.3 || r_c > 2.2) continue;
        double r_m = r_c - 0.5 * dr, r_p = r_c + 0.5 * dr;
        double dV_r = (r_p*r_p*r_p - r_m*r_m*r_m) / 3.0;
        for (int ith = NGHOST + 2; ith < nth + NGHOST - 2; ++ith) {
            double th_c = th_min + (ith - NGHOST + 0.5) * dth;
            double d_mu = cos(th_c - 0.5*dth) - cos(th_c + 0.5*dth);
            double sin_c = sin(th_c);
            for (int iph = 0; iph < nph; ++iph) {
                int c = idx3d(ir, ith, iph, nr_tot, nth_tot, nph);
                int cp_r = idx3d(ir + 1, ith, iph, nr_tot, nth_tot, nph);
                int cm_r = idx3d(ir - 1, ith, iph, nr_tot, nth_tot, nph);
                int cp_t = idx3d(ir, ith + 1, iph, nr_tot, nth_tot, nph);
                int cm_t = idx3d(ir, ith - 1, iph, nr_tot, nth_tot, nph);
                int cp_p = idx3d(ir, ith, iph + 1, nr_tot, nth_tot, nph);
                int cm_p = idx3d(ir, ith, iph - 1, nr_tot, nth_tot, nph);

                double br_p = 0.5 * (h_U[4*ncells + c] + h_U[4*ncells + cp_r]);
                double br_m = 0.5 * (h_U[4*ncells + c] + h_U[4*ncells + cm_r]);
                double bt_p = 0.5 * (h_U[5*ncells + c] + h_U[5*ncells + cp_t]);
                double bt_m = 0.5 * (h_U[5*ncells + c] + h_U[5*ncells + cm_t]);
                double bp_p = 0.5 * (h_U[6*ncells + c] + h_U[6*ncells + cp_p]);
                double bp_m = 0.5 * (h_U[6*ncells + c] + h_U[6*ncells + cm_p]);

                double divB = (r_p*r_p*br_p - r_m*r_m*br_m) / dV_r
                            + (sin(th_c + 0.5*dth)*bt_p - sin(th_c - 0.5*dth)*bt_m) / (r_c * d_mu)
                            + (bp_p - bp_m) / (r_c * sin_c * dph);
                double bmag = std::sqrt(h_U[4*ncells+c]*h_U[4*ncells+c] + h_U[5*ncells+c]*h_U[5*ncells+c] + h_U[6*ncells+c]*h_U[6*ncells+c]);
                double h_cell = std::cbrt(dr * (r_c * dth) * (r_c * sin_c * dph));
                double vol = dV_r * d_mu * dph;
                num_divb += vol * h_cell * std::fabs(divB);
                den_b += vol * bmag;
            }
        }
    }
    double weighted_divb = (den_b > 1e-12) ? (num_divb / den_b) : 0.0;
    printf("Weighted dimensionless magnetic divergence <h|divB|> / <|B|> = %.5e\n", weighted_divb);

    std::ofstream fmeta(cfg.out_prefix + "_run_meta.json");
    fmeta << "{\n"
          << "  \"mode\": \"" << cfg.mode << "\",\n"
          << "  \"bc_file\": \"" << cfg.bc_file << "\",\n"
